TP.register({id:"lp3-g1",lp:3,grade:"1",mode:"curriculum",checks:2,nextGrade:"2nd grade",build(E){const F=E.F;const ico=(n,px)=>(F.icon||F.pic2)(n,px)||n;const FROST="Frost is on the grass. It is crisp and wet. Val has on a thick red vest. She runs up the hill. The pumpkin patch is at the top. Crunch, crunch, crunch! Then Val stops. A chipmunk sits on a log. It has a nut. Val is still as a rock. The chipmunk grabs the nut. Then it runs off. Val grins. She picks a fat, round pumpkin. She will set it on the step at home.";const JOB="Jill grew the best pumpkin in the whole patch. But it was so big! She tried to lift it, but it would not budge. “I need help,” said Jill. She ran down the road to get her friend Russ. Russ had a red wagon. Together they rolled the pumpkin up a board and set it in the wagon. Then they had to tug and tug. Up the hill they went, one slow step at a time, all the way to the fair.";const PUMP="A pumpkin grows on a long stem that stays joined to the vine. It has thick skin that keeps it safe. Sun and wet mud help it get big. Some pumpkins can get as big as a dog! When you cut one open, you will see wet pulp and lots of seeds inside.";const SUNF="Sunflowers are tall plants with big yellow flowers. A young sunflower turns to face the sun as the sun moves across the sky. Each flower is full of seeds. Birds love to eat the seeds, and people eat them too. Farmers plant sunflower seeds in the spring. The flowers bloom in late summer and fall.";const WORDS=["duck","bell","fluff","chill","drift","stump","swing","honk","rocks","basket","have","sneck"];const CORN="corn",SUNFL="sunflower";function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}function tens(t,o){return F.blocks(0,t,o)}const INK=window.TP_ICON_INK||"#6B4A3C";const eye=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const blush=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const smile=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4));const PK_ART=`<path d="M-7 -27 L-5 -45 q0 -5 6 -5 q6 0 6 5 L9 -26 Z" fill="#B08E63" stroke="${INK}" stroke-width="3.4"/><path d="M-7 -34 q-15 -7 -18 3 q13 7 18 -3 Z" fill="#A8D49A" stroke="#4E7A46" stroke-width="3"/><ellipse cx="0" cy="0" rx="44" ry="33" fill="#F7A657" stroke="${INK}" stroke-width="3.4"/><path d="M-8 -31 C-36 -21 -36 21 -8 31 M8 -31 C36 -21 36 21 8 31" fill="none" stroke="#DD8437" stroke-width="2.6"/>`+FACE(0,-3,15,5);function pumpkin(w){return`<svg viewBox="0 0 100 92" width="${w}" role="img" aria-label="pumpkin" style="vertical-align:middle"><g transform="translate(50 57)" stroke-linejoin="round" stroke-linecap="round">${PK_ART}</g></svg>`}function seed(w){return`<svg viewBox="0 0 100 92" width="${w}" role="img" aria-label="seed"><g stroke-linejoin="round" stroke-linecap="round"><path d="M50 11 C80 31 78 73 50 84 C22 73 20 31 50 11 Z" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/><path d="M50 21 C59 29 61 36 60 44" fill="none" stroke="#C9B49A" stroke-width="3"/><g transform="translate(50 49) scale(.84)">${FACE(0,-1,13,4)}</g></g></svg>`}function emo(e){return`<span style="font-size:3.4rem;line-height:1" aria-hidden="true">${ico(e,54)}</span>`}function growChart(){const steps=[[seed(70),"seed"],[emo("sprout"),"sprout"],[emo("purpleFlower"),"flower"],[ico("pumpkin",84),"pumpkin"]];return`<div class="figure" style="align-items:stretch;gap:10px;flex-wrap:wrap">${steps.map((s,i)=>`<div style="border:3px solid var(--line);border-radius:16px;padding:8px 14px;min-width:120px;text-align:center;display:flex;flex-direction:column;justify-content:space-between"><p class="fig-label" style="margin:0">${i+1}</p><div style="min-height:84px;display:flex;align-items:center;justify-content:center">${s[0]}</div><p class="fig-label" style="margin:0">${s[1]}</p></div>${i<3?`<span class="big" style="align-self:center" aria-hidden="true">→</span>`:""}`).join("")}</div>`}function pickGraph(){const rows=[["Corn",6,()=>`<span style="font-size:2rem">${ico(CORN,32)}</span>`],["Sunflowers",9,()=>`<span style="font-size:2rem">${ico(SUNFL,32)}</span>`],["Pumpkins",4,()=>ico("pumpkin",40)]];return`<div class="figure"><table class="chart" role="img" aria-label="Picture graph: What We Picked"><caption style="font-family:var(--font-display);font-weight:700;font-size:1.4rem;padding-bottom:6px">What We Picked</caption>${rows.map(r=>`<tr><th style="text-align:left;padding:6px 16px;font-size:1.3rem">${r[0]}</th><td style="text-align:left;padding:6px 12px;white-space:nowrap">${Array.from({length:r[1]},r[2]).join(" ")}</td></tr>`).join("")}</table></div>`}function pics(list){return`<div class="figure">${list.map(x=>F.pic(x[0],x[1],"3.6rem")).join("")}</div>`}function unitsFig(){const w=760,h=270,u=56,x0=90;let s=`<svg viewBox="0 0 ${w} ${h}" width="${w}" role="img" aria-label="Two vines measured with square blocks laid end to end. One vine has yellow blocks. One vine has purple blocks.">`;s+=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const row=(y,n,fill,bc)=>{let b=`<rect x="${x0}" y="${y}" width="${n*u}" height="28" rx="8" fill="${fill}" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<n;i++)b+=`<rect x="${x0+i*u}" y="${y+40}" width="${u}" height="34" fill="${bc||'#F2DC9A'}" stroke="var(--fig-ink)" stroke-width="3"/>`;return b};s+=row(50,5,"#A8D49A","#F2C01E");s+=row(168,3,"#A8D49A","#8E5BC9");return s+"</svg>"}function unequalCircle(){return`<svg viewBox="0 0 160 160" width="160" role="img" aria-label="A circle cut into two parts that are not the same size"><circle cx="80" cy="80" r="70" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="4"/><line x1="50" y1="16.8" x2="50" y2="143.2" stroke="var(--fig-ink)" stroke-width="4"/></svg>`}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const STOPS=[{id:1,title:"Corn Row Sounds",short:"Corn Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<div style="text-align:center;margin:8px 0"><img alt="Six pictures: a vine, a stack of books, a seed sprouting, corn growing in a row, a hay bale, and a straw hat" src="data:image/webp;base64,${window.TP_IMG1.wp.cornsounds}" style="width:680px;max-width:100%;height:auto"></div><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend: /v/ /ī/ /n/ (vine)","Blend: /s/ /t/ /a/ /k/ (stack)","What is the last sound in patch? (/ch/)","What is the middle sound in seed? (/ē/, long e)","Say all the sounds in crop. (/k/ /r/ /o/ /p/)","Which word has a long vowel sound: hay or hat? (hay)"],desc:"blending, isolating, and segmenting sounds and telling long from short vowels in spoken words"}]},{id:2,title:"Harvest Wagon Math",short:"Wagon Math",parts:[{std:["1.OA.A.1"],dur:140,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<p class="huge" style="font-size:3rem;margin:0" aria-hidden="true">${ico("tractor",48)} ${ico("pumpkin",64)} ${ico("pumpkin",64)}</p>`,qs:["7 pumpkins are on the vine. 6 more pumpkins are on the wagon. How many pumpkins in all?","12 ducks are at the pond. 4 ducks swim away. How many ducks are left?","Nell picks 8 sunflowers. Omar picks 5 sunflowers. How many more sunflowers does Nell pick?","There are 14 hay bales. 9 are in the barn. The rest are on the wagon. How many are on the wagon?","Some birds sit on the fence. 3 more birds come. Now there are 11 birds. How many birds were there at the start? Write a number sentence with a box and hold it up."],key:["13 pumpkins (7 + 6 = 13)","8 ducks (12 - 4 = 8)","3 more sunflowers (8 - 5 = 3 or 5 + 3 = 8)","5 hay bales (9 + 5 = 14 or 14 - 9 = 5)","8 birds. Writes □ + 3 = 11 or 11 - 3 = □"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:3,title:"Words on the Vine",short:"Vine Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,wordPics:1,n:12,dur:95,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. sneck is a silly word: listen for sn and the ck ending.","Watch for: ck and double letters (duck, bell, fluff, chill), blends at the start and end (drift, stump), ng and nk (swing, honk), ending -s (rocks), two parts (basket), tricky word (have)."],desc:"reading words with digraphs, blends, double letters, endings, and two syllables"}]},{id:4,title:"Hay Bale Hops",short:"Hay Hops",parts:[{std:["1.OA.C.5"],dur:100,dir:"Count out loud like you are hopping on hay bales. Say each answer.",html:()=>`<p class="huge" style="font-size:3.2rem;margin:4px 0" aria-hidden="true">${ico("rabbit",52)} ${ico("wheat",52)} ${ico("wheat",52)} ${ico("wheat",52)}</p>`,qs:["Start at 9. Count on 4. Where do you land? What adding sentence is that?","Start at 15. Count back 3. Where do you land? What take away sentence is that?","Solve 3 + 8 by counting on. Which number is faster to start at? Say the numbers you count.","Solve 12 - 9. Start at 9 and count up to 12. How many hops is that?","True or silly? To solve 14 - 2, the scarecrow counts: 14, 13. The scarecrow says the answer is 13."],key:["Counts 10, 11, 12, 13. Lands on 13. 9 + 4 = 13","Counts 14, 13, 12. Lands on 12. 15 - 3 = 12","Starts at 8. Counts 9, 10, 11. Answer 11","Counts 10, 11, 12. That is 3 hops, so 12 - 9 = 3","Silly. Do not count the 14 as a hop. Count back two: 13, 12. The answer is 12"],desc:"counting on and counting back or up to add and subtract"}]},{id:5,title:"Frosty Morning Read",short:"Frosty Read",parts:[{std:["RF.1.4"],kind:"read",n:72,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",html:()=>`<p class="huge" style="font-size:3rem;margin:0" aria-hidden="true">${ico("squirrel",48)} ${ico("leaf",48)}</p>${story("Frost",FROST)}`,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Val runs up a frosty hill toward the pumpkin patch, stops to look at a chipmunk with a nut on a log, watches it run off, then carries a pumpkin up the steps at home" src="data:image/webp;base64,${window.TP_IMG1.wp.frost}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["72 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace, expression (Crunch, crunch, crunch!), and whether the student rereads to fix a mistake.","Quick check after reading: What did the chipmunk grab? (the nut)"],desc:"a 72-word decodable story read aloud"}]},{id:6,title:"Hay Bale Stacks",short:"Hay Stacks",parts:[{std:["1.NBT.B.2"],dur:100,dir:"Look at the stacks. Each tall stack is 1 ten. Answer out loud.",fig:()=>`<div class="figure" style="align-items:flex-end;gap:60px"><div>${tens(3,4)}<p class="fig-label">Stack A</p></div><div>${tens(5,0)}<p class="fig-label">Stack B</p></div></div>`,qs:["Look at Stack A. How many tens? How many ones? What number is it?","Look at Stack B. How many tens? How many ones? What number is it?","How many tens and ones are in 17?","What does the 6 in 62 mean?","Riddle: I have 4 tens and 9 ones. What number am I?","True or silly? 28 has 8 tens and 2 ones."],key:["3 tens and 4 ones. The number is 34","5 tens and 0 ones. The number is 50","1 ten and 7 ones","6 tens, or 60","49","Silly. 28 has 2 tens and 8 ones"],desc:"tens and ones in two-digit numbers"}]},{id:7,title:"The Big Pumpkin Job",short:"Big Job",parts:[{std:["RL.1.1"],dur:100,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("A Big Job",JOB),picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Jill hugs a huge pumpkin, then tries to lift it. She runs to get Russ and his red wagon. They roll it up a ramp, pull the wagon up the hill, and win a blue ribbon" src="data:image/webp;base64,${window.TP_IMG1.wp.wagonpump}" style="width:720px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["What did Jill have?","Who did Jill run to get?","Where did Jill and Russ set the pumpkin?","Ask me a question about the story."],key:["The best pumpkin (a big pumpkin)","Russ","In the red wagon","Asks a real question about the story, such as: Where did they take the pumpkin? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:8,title:"How a Pumpkin Grows",short:"It Grows",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:80,dir:"Look at the pictures. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">How does a pumpkin start? What comes next? Use the pictures.</p>`,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Six pictures with arrows: a seed in soil, a sprout with roots, a vine with a flower, a small green pumpkin, a big orange pumpkin, and a happy ripe pumpkin in the sun" src="data:image/webp;base64,${window.TP_IMG1.wp.pumpgrow}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Finds the answer in the pictures. Your help is fine: point to the first picture and read the question again","Writes an answer that uses the pictures: it starts as a seed, and next comes a sprout","The answer fits the question: it tells how a pumpkin starts"],desc:"using pictures to answer a question in writing"}]},{id:9,title:"Harvest Count",parts:[{std:["1.MD.C.4"],dur:100,dir:"Look at the picture graph. Answer out loud.",fig:()=>pickGraph(),qs:["How many sunflowers did we pick?","How many more sunflowers than corn?","How many fewer pumpkins than corn?","How many things did we pick in all?","Ask me your own question about the graph."],key:["9 sunflowers","3 more (9 - 6 = 3)","2 fewer (6 - 4 = 2)","19 in all (6 + 9 + 4 = 19)","Asks a question the graph can answer, such as: Which row has the most? How many pumpkins?"],desc:"reading a picture graph with three categories and asking and answering questions about it"}]},{id:10,title:"Pumpkin Facts",parts:[{std:["RI.1.1"],dur:100,dir:"Read about pumpkins out loud. Then listen to each question and answer out loud.",html:()=>`<p style="text-align:center;margin:0">${ico("pumpkin",72)}</p>${story("Pumpkins",PUMP)}`,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="A smiling pumpkin on a vine with labels: it grows on a long stem, it has thick skin, sun and wet mud help it get big, it can get as big as a dog, and a cut pumpkin has wet pulp and seeds inside" src="data:image/webp;base64,${window.TP_IMG1.wp.pumpfacts}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["What kind of skin does a pumpkin have?","What helps a pumpkin get big?","What will you see if you cut a pumpkin?","Ask me one question about pumpkins."],key:["Thick skin","The sun and wet mud (both, or one with a prompt)","Wet pulp","Asks a real question about pumpkins, such as: How long does it take to grow? If stuck, say: Start with what, how, or why."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:11,title:"Corn Row Tricks",short:"Corn Tricks",parts:[{std:["1.OA.B.3"],dur:90,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${ico(CORN,48)} ${ico(CORN,48)} ${ico(CORN,48)}</p>`,qs:["5 + 9 = 14. So what is 9 + 5?","True or silly? 6 + 7 is the same as 7 + 6.","Add 3 + 5 + 7. Which two numbers would you add first? Why?","Add 8 + 6 + 2.","Solve 9 + 4. Break the 4 into 1 and 3 to make a ten."],key:["14. Knows it without counting because the numbers just switch places","True. The order does not change the total. Both make 13","15. Adds 3 + 7 to make 10, then 10 + 5","16. Adds 8 + 2 to make 10, then 10 + 6","13. 9 + 1 = 10, then 10 + 3 = 13"],desc:"using turn-around facts and making ten as strategies to add"}]},{id:12,title:"Patch Writer",short:"Write",parts:[{wk:"facts",alt:{group:"write",label:"Fall Facts",icon:"🍂",hint:"Tell 2 facts about fall"},std:["W.1.2"],n:3,label:"checks met",dur:210,dir:WDIR,html:()=>`<p class="big">Write about fall. Tell 2 facts about fall.</p>${TWO}`,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Four fall pictures: a tree with falling red and orange leaves, a cold frosty field with a thermometer and snowflake sign, a basket of red apples under an apple tree, and a big pumpkin and a little pumpkin on the vine" src="data:image/webp;base64,${window.TP_IMG1.wp.fallfacts}" style="width:640px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Names the topic: fall (W.1.2)","Gives at least 2 facts about fall, such as leaves drop, the air gets cool, or crops are picked (W.1.2)","Gives some sense of closure, such as: That is what fall is like (W.1.2)"],desc:"an informative piece with facts about fall"},{wk:"story",alt:{group:"write",label:"Biggest Pumpkin Story",icon:"🚜",hint:"Tell what happens first, next, and last"},std:["W.1.3"],n:4,label:"checks met",dur:210,dir:WDIR,html:()=>`<p class="big">Write a story about the day you find the biggest pumpkin ever. Tell what happens first, next, and last.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>${TWO}`,key:["Tells 2 or more events in order (W.1.3)","Includes some details about what happened (W.1.3)","Uses time words such as first, next, then, or last (W.1.3)","Gives some sense of closure (W.1.3)"],desc:"a narrative about finding the biggest pumpkin"}]},{id:13,title:"Scarecrow Sentence Check",short:"Sentences",parts:[{title:"Sentence Count",std:["RF.1.1"],dur:45,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">Ducks swim in the pond. Look at them go!</p>`,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="A mother duck and three ducklings swimming in a pond with autumn trees" src="data:image/webp;base64,${window.TP_IMG1.wp.ducks}" style="width:560px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the last sentence. What kind of letter does it start with?","What is the mark at the end of the last sentence called? What does it tell you?","Spot the mistake. Look at the sentence in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">can a duck run</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","Look. It starts with a capital (uppercase) L","An exclamation mark (exclamation point). It tells you to read it with strong feeling","It needs a capital C at the start and a question mark at the end, because it asks something"],desc:"finding sentences by their capital letters and end marks"},{title:"Scarecrow Fix It",std:["L.1.1"],dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today I pick a pumpkin. Yesterday I ____ a pumpkin.","Which sounds right? This pumpkins are big. These pumpkins are big.","Which sounds right? Me see a duck. I see a duck.","Finish it: I put on a coat because ____.","Add a word that tells where: The scarecrow stands ____ the corn.","Ask a question that starts with Where."],key:["picked (past tense)","The second one: these, because there is more than one pumpkin","The second one: I see a duck","Any ending that gives a reason, such as: it is cold","Any word that tells where and fits, such as in, by, near, or behind","Any whole question that starts with Where, such as: Where is the wagon?"],desc:"spoken grammar items (past tense, this and these, pronoun I, because, where words, asking sentences)"}]},{id:14,title:"Sunflower Chat",short:"Sunflowers",parts:[{title:"Sunflower Listen",std:["SL.1.2"],n:4,dur:80,read:SUNF,dir:"Listen carefully. Your teacher will read about sunflowers. Then answer out loud.",html:()=>``,picSup:true,fig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Six sunflower pictures with short labels: sunflowers are tall with big yellow flowers, a young sunflower turns to face the sun, each flower is full of seeds, birds and people eat the seeds, farmers plant seeds in spring, and flowers bloom in late summer and fall" src="data:image/webp;base64,${window.TP_IMG1.wp.sunfacts}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Ask: What does a young sunflower turn to face? (the sun)","Ask: Who eats sunflower seeds? (birds and people; one is enough)","Ask: When do farmers plant the seeds? (in the spring)","Say: Ask me one question about sunflowers. (asks 1 question that is about what was read and starts with a question word, such as: How tall do they get?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About a Friend",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about someone you like to play with.</p><ul class="qlist" style="margin-top:14px"><li>Who is it?</li><li>What do you do together?</li><li>How do you feel when you play?</li></ul>`,key:["Names the person and gives 2 or more details about who they are or what they are like (SL.1.4)","Names 1 or more things they do together and gives 1 or more details about it, all about this one person (SL.1.4)","Says how playing together makes them feel, in at least 1 complete sentence (SL.1.4)"],desc:"describing a person and what they do together with relevant details"}]},{id:15,title:"Which One Wins",short:"Opinion",parts:[{wk:"opinion",std:["W.1.1"],n:3,label:"checks met",dur:75,dir:WDIR,desc:"a short opinion piece with a reason and a closing",html:()=>`<p class="big">Which would you rather take home from the patch: a pumpkin or a sunflower?</p><p class="big">Write 2 or 3 sentences. Tell which one you pick, tell why, and end it.</p><div class="figure">${ico("pumpkin",96)}${ico(SUNFL,96)}</div>`,key:["Names what the writing is about and states an opinion, such as: I would take home a pumpkin. (W.1.1)","Gives a reason for the opinion, such as: because I can grow seeds from it. (W.1.1)","Ends with a closing line, such as: That is why I pick a pumpkin. A short last line counts. (W.1.1)","Spelling and handwriting are not scored here. Read the piece back with the student if it is hard to read."]}]},{id:16,title:"Count the Whole Patch",short:"To 120",parts:[{std:["1.NBT.A.1"],n:3,dur:55,dir:"Count out loud. Then read the numbers.",html:()=>`<p class="big" style="text-align:center">Start at 108. Count out loud to 120.</p>`,fig2:()=>F.cards(["87","103","120"],{size:"2.8rem",min:120}),key:["Counts 108, 109, 110 and on to 120 with no skips. Listen at 109 to 110 and at 119 to 120.","Reads the three cards: eighty-seven, one hundred three, one hundred twenty.","Say: Write the number that is one more than 99. Hold it up. (100)"],desc:"counting to 120 from a number other than 1, and reading and writing numerals"}]},{id:17,title:"Load the Wagon",short:"Add Tens",parts:[{title:"Add It On",std:["1.NBT.C.4"],n:3,dur:60,dir:"Look at the blocks. Answer out loud. You can use your paper.",fig:()=>F.row([tens(3,4),"34"]),qs:["The wagon holds 34 pumpkins. 5 more go in. How many now?","Start with 34 again. 20 more pumpkins go in. How many now?","Solve 58 + 30. Tell me what you added to what."],key:["39. Adds 5 ones to 4 ones, so the tens stay at 3.","54. Adds 2 tens to 3 tens, so the ones stay at 4.","88. Looks for: I added the tens to the tens, 5 tens and 3 tens is 8 tens, and the 8 ones stayed."],desc:"adding a one-digit number and a multiple of ten to a two-digit number"},{title:"Take Tens Away",std:["1.NBT.C.6"],n:3,dur:50,dir:"Answer out loud. The blocks can help.",fig:()=>F.row([tens(7,0),"70"]),qs:["70 - 30","90 - 60","Solve 50 - 50. Tell me how you know."],key:["40. 7 tens take away 3 tens is 4 tens.","30. 9 tens take away 6 tens is 3 tens.","0. Taking away all 5 tens leaves nothing."],desc:"subtracting multiples of ten from multiples of ten"}]},{id:18,title:"Measure and Time",short:"Measure",parts:[{title:"How Many Blocks",std:["1.MD.A.2"],n:3,dur:55,dir:"Look at the two vines. The blocks are all the same size. Answer out loud.",fig:()=>F.row(unitsFig()),supfig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Two vines with same-size blocks laid end to end. The top vine has 5 yellow blocks. The bottom vine has 3 purple blocks." src="data:image/webp;base64,${window.TP_IMG1.wp.blocks19}" style="width:560px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["How many blocks long is the yellow vine?","How many blocks long is the purple vine?","How much longer is the yellow vine than the purple vine?"],key:["5 blocks. The blocks are end to end with no gaps, so counting them gives the length.","3 blocks","2 blocks longer (5 - 3 = 2)"],desc:"measuring length with same-size units laid end to end"},{title:"Patch Clock",std:["1.MD.B.3"],n:3,dur:55,dir:"Look at the clocks. Say the time. Then write it on your paper.",fig:()=>F.row([F.clock(3,0,200),"A"],[F.clock(7,30,200),"B"]),supfig:()=>`<div style="text-align:center;margin:8px 0"><img alt="A clock face. The short red hour hand points to the 10. The long blue minute hand points to the 12. Big numbers 1 to 12 are the hours. Small labels around the edge count minutes by fives, from :00 to :55." src="data:image/webp;base64,${window.TP_IMG1.wp.clocklab}" style="width:340px;max-width:100%;height:auto"></div>`,qs:["Clock A: what time is it? Write it.","Clock B: what time is it? Write it.","Someone writes 4:00. Where would the hour hand point? Where would the minute hand point?"],key:["3 o'clock. Writes 3:00","Half past 7, or seven thirty. Writes 7:30","The hour hand points at the 4 and the minute hand points at the 12."],desc:"telling and writing time to the hour and half hour"}]},{id:19,title:"Share It Fair",short:"Halves",parts:[{std:["1.G.A.3"],n:4,dur:55,dir:"Look at the three pictures. Answer out loud.",fig:()=>F.row([F.fracCircle(2,1,150),"1"],[F.gridRect(1,4,1,{cell:56}),"2"],[unequalCircle(),"3"]),supfig:()=>`<div style="text-align:center;margin:8px 0"><img alt="Two pumpkin pies. The left pie is cut into 2 equal parts with 1 part colored orange. The right pie is cut into 4 equal parts with 1 part colored orange." src="data:image/webp;base64,${window.TP_IMG1.wp.pies20}" style="width:640px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["Picture 1. Ask: This circle is cut into 2 equal parts. What do we call one of those parts? (a half)","Picture 2. Ask: This rectangle is cut into 4 equal parts. What do we call one of those parts? (a fourth, or a quarter)","Picture 3. Ask: Is this circle cut into halves? How do you know? (No. The two parts are not the same size.)","Ask: You take one half of a pumpkin pie, or one fourth of the same pie. Which piece is bigger? (one half. More equal parts means smaller pieces.)"],desc:"halves and fourths of circles and rectangles, and comparing the size of the parts"}]},{id:20,title:"Copy a Squirrel",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A squirrel has stretchy pouches. They are inside its cheeks. It can fill them with acorns. A dozen will fit. It can still run and climb. Every foot is free.</p>
     <div class="figure">${ico("squirrel",104)}${ico("acorn",88)}</div>
     <p class="big">A worker is saving pumpkin seeds. She has to keep stopping. That is because both hands are full. The seeds keep spilling.</p>`,qs:["How do cheek pouches help a squirrel carry a lot of acorns at once?","Draw something the worker could wear that copies the squirrel's cheek pouches.","Tell me which animal part you copied and how your design leaves both hands free."],key:["The acorns ride inside the squirrel instead of in its paws, so all four feet stay free for running and climbing. Any answer about carrying while keeping the feet or hands free counts.","Any wearable holder: an apron with a front pocket, a pouch on a belt, a sack hung on a strap, a bag tied at the waist. A basket carried in the hands is partial, so ask what the squirrel's trick really is.","Needs both halves: names the cheek pouch as the part copied, and says the load rides on the body so the hands stay free."]}]},{id:21,title:"Squirrel Parents",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"A squirrel has built a nest of leaves in the oak at the edge of the patch. Her three young are old enough to climb, but not yet old enough to find food on their own. Every morning she comes down the trunk first and waits at the bottom. Only when she gives a soft chuckle do the young come down after her. She walks to a spot in the grass, digs with both front paws, and lifts out an acorn she buried weeks ago. The young crowd in and dig in the same spot.",qs:["What do the young do every morning after the parent gives her soft chuckle?","What do the young do once the parent starts digging in the grass?","How does coming down only after the parent calls help the young squirrels?"],key:["They come down the trunk after her. Every morning is what makes it a pattern.","They crowd in and dig in the same spot she chose.","She has already been down and had a look round, so they come to a place she has checked. They also learn which spots are worth digging by copying her."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A pumpkin seedling and the grown pumpkin plant it came from. A young squirrel and its parent.</p>
     <div class="figure">${ico("sprout",92)}${ico("pumpkin",104)}</div>
     <div class="figure">${ico("squirrel",92)}${ico("squirrel",112)}</div>`,qs:["Name one way the pumpkin seedling is like the grown pumpkin plant.","Name one way the seedling is not exactly like the grown plant.","The young squirrel has a thinner tail and shorter legs than its parent. Will it always be different in those ways? Say what you think happens as it grows."],key:["Both are green plants with leaves on a stem, both grow from the ground. Any likeness counts.","The seedling is tiny, it has only two leaves, it has no vine and no pumpkin. Any difference counts.","No. It will grow and come to look much more like its parent, but even grown it will not be exactly the same. Both halves are worth hearing: it changes as it grows, and it never becomes identical."]}]},{id:22,title:"Stars Over the Patch",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the star log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">At eight o'clock on four clear nights the farmer wrote down where one group of bright stars was.</p>
     <table class="bigTable"><tr><th>Night</th><th>Where the star group was at eight o'clock</th></tr>
     <tr><td>Monday</td><td>just over the barn roof</td></tr>
     <tr><td>Tuesday</td><td>just over the barn roof</td></tr>
     <tr><td>Wednesday</td><td>just over the barn roof</td></tr>
     <tr><td>Thursday</td><td>just over the barn roof</td></tr></table>
     <div class="figure">${ico("star",88)}${ico("moon",88)}${ico("scarecrow",88)}</div>`,qs:["Where was the star group at eight o'clock on every one of the four nights?","Friday is clear too. Where do you predict the star group will be at eight o'clock?","What in the log makes you sure enough to predict it?","At midnight that same group is not over the barn any more. Does that mean the stars are gone, or that they have moved across the sky as the night goes on?"],key:["just over the barn roof","just over the barn roof again","It was in the same place at the same hour on all four nights. A thing that repeats is a pattern, and a pattern lets you predict.","They have moved across the sky. They are still there, just in a different place, which is itself a pattern that repeats every night."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">The farmer wrote down the time the sun went down on the first day of three months in a row.</p>
     <table class="bigTable"><tr><th>Month</th><th>Time the sun went down</th></tr>
     <tr><td>October</td><td>6:30</td></tr><tr><td>November</td><td>5:00</td></tr>
     <tr><td>December</td><td>4:30</td></tr></table>`,qs:["In which of the three months did the sun go down earliest?","Is the sun going down earlier or later as the months go by?","The patch closes when it gets dark. Will it have to close earlier in December than it did in October? Use the chart to say why."],key:["December, at 4:30","earlier each month","Yes, much earlier. In October the light lasted until 6:30 and in December only until 4:30, so there are two fewer hours of daylight at the end of the day."]}]},{id:23,title:"Sound in the Patch",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a dry gourd or a jar with seeds in it, shake it first. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Put a handful of dry pumpkin seeds in a jar and shake it hard. Then hold the jar still.</p>
     <div class="figure">${ico("pumpkin",96)}${ico("pan",96)}</div>
     <p class="big">Now lay a small scrap of paper on top of an upside down metal pan. Bang a second pan hard right next to it, without touching the first one.</p>`,qs:["What has to happen to the seeds inside the jar before you hear anything?","Hold the jar perfectly still. Is there any sound? Say why.","When the second pan is banged, what does the paper scrap on the first pan do?","Nothing touched the paper scrap. What does its jump tell you about sound?"],key:["They have to move, knock about, shake against the glass and each other.","No sound. Nothing is moving or shaking, and with no shaking there is no sound.","It hops, jumps, slides, or flutters.","A sound can make a thing shake from across a gap. The banged pan made the air and then the first pan shake, and that shaking tossed the paper."]}]},{id:24,title:"In the Dark Shed",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The tool shed at the edge of the patch has no window and the door is shut.</p>
     <div class="figure">${ico("pumpkin",96)}${ico("torch",96)}</div>`,qs:["A big orange pumpkin is sitting in the shed with the door shut. Can you see it? Say why or why not.","What has to happen before anyone can see it?","A white sheet is in the same dark shed. Is white easier to see than orange when there is no light at all? Say why."],key:["No. There is no light in the shed, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: a lamp or a flashlight switched on, or the door opened so daylight gets in.","No. With no light at all nothing can be seen, whatever color it is. Color only matters once there is light to bounce off it."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">In the dark shed one flashlight beam was pointed at four things, and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear plastic bag</td><td>went straight through</td></tr>
     <tr><td>a dry corn husk</td><td>a little came through, glowing faintly</td></tr>
     <tr><td>a thick wooden plank</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a sheet of kitchen foil</td><td>bounced straight back</td></tr></table>`,qs:["Which thing stopped the beam completely?","Which thing let only a little light through?","You hold the corn husk up and look at a hand behind it. Do you see the hand clearly, a dim shape, or nothing at all?","You want a very dark shadow on the shed wall for a shadow show. Which of the four would you hold up, and why?"],key:["the thick wooden plank","the dry corn husk","a dim shape. Some light gets through a husk, but not enough to see the hand clearly.","the thick wooden plank, because it stops all the light and leaves a dark shadow behind it. The foil is wrong here, because it sends the light back the other way."]}]},{id:25,title:"Across the Big Field",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The pumpkin field is wide and the wagon driver waits at the far gate. Shouting does not carry that far across open ground.</p>
     <div class="figure">${ico("scarecrow",88)}${ico("lantern",88)}${ico("megaphone",88)}</div>`,qs:["Draw a device that tells the driver at the far gate to bring the wagon over. It has to use light or sound.","What did you draw, and does it send its message with light or with sound?","Night is coming and it is getting hard to see. Would your device still work? If not, say what you would change."],key:["Any device that carries light or sound across the field: a bell, a horn, a whistle, a drum, a bright lamp raised on a pole, a lamp flashed on and off.","Names it and says which one it uses.","A sound device still works in the dark. A device that waves a flag or a cloth does not, and the student should say they would switch to a light or a sound. Honest reasoning matters more than which answer they started with."]}]},{id:26,title:"Fix the Tipping Barrow",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"The workers carry pumpkins out of the field in a wheelbarrow with one wheel at the front. With one pumpkin in it, the barrow rolls fine. With three pumpkins in it, the barrow leans to one side partway along the row and a pumpkin rolls off into the dirt.",qs:["What is the problem the workers want to change?","Ask me a question about this problem that would help you solve it.","Before you build anything, what would you go and look at first?"],key:["The wheelbarrow leans and a pumpkin rolls off when three are loaded in.","Any real question: how heavy is a pumpkin, where in the barrow are they put, is the ground bumpy, how wide is the barrow, which side does it lean to. A statement is not a question, so ask once more.","Any real observation: which side it leans to, how far along the row it happens, how the pumpkins are arranged, whether it happens on flat ground too."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw a better wagon or barrow for carrying three pumpkins out of the field.</p>
     <div class="figure">${ico("pumpkin",88)}${ico("box",88)}${ico("tractor",88)}</div>`,qs:["Draw your fix.","Point to the part that keeps the pumpkins in and tell me its shape.","Tell me why your shape stays upright better than a barrow with one wheel at the front."],key:["Any real fix: a wider box, a rim or wall round the edge, two or four wheels instead of one, dips or hollows for each pumpkin to sit in, a strap across the top.","Names a shape: a tall rim all the way round, a wide flat bottom, round hollows, a low box.","Because a wide bottom or extra wheels spread the load across more ground, so it cannot tip onto one side the way one wheel can."]}]},{id:27,title:"Which Wagon Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two wagons were tested down the same bumpy row, twelve pumpkins in each, three trips each.</p>
     <table class="bigTable"><tr><th>Wagon</th><th>Pumpkins that rolled off, out of 12</th></tr>
     <tr><td>a flat bed with no rim</td><td>7</td></tr>
     <tr><td>a bed with a tall rim</td><td>0</td></tr></table>`,qs:["Which wagon worked better in the test?","Use the two numbers in the chart to tell me how you know.","Both wagons were pulled down the same row with the same number of pumpkins. Why does that matter when you compare them?"],key:["the bed with a tall rim","Not one pumpkin out of 12 rolled off the wagon with the rim, and 7 out of 12 rolled off the flat bed. The numbers have to be in the answer.","Because then the only thing that is different is the wagon itself. If one had gone down a smooth row you would not know whether the wagon or the road made the difference."]}]},{id:28,title:"Being a Good Neighbor",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Answer out loud.",desc:"telling a right from a responsibility and naming responsibilities that come with living in a community",html:()=>`<p class="big">Think about the park, the sidewalk, and the crossing near where you live. They belong to everybody.</p>
     <p class="big">There is an old saying. People call it the Golden Rule. Treat other people one way. Treat them as you want them to.</p>
     <div class="figure">${ico("tree",88)}${ico("bus",88)}${ico("hands",88)}</div>`,qs:["Anybody in town is allowed to play at the public park. Is being allowed to use it a right or a responsibility?","Picking up your own wrapper before you leave the park is something you do. Is that a right or a responsibility?","A crossing guard holds up a hand and you stop. Why do people follow a rule like that even when they are in a hurry?","People call one old saying the Golden Rule. Say it in your own words, and give one thing you would do at the park if you followed it."],key:["a right","a responsibility","Because the rule keeps everybody safe, not just you, and a town only works if people follow the rules they share. Any answer about safety or about everyone keeping to it counts.","Treat other people the way you would want them to treat you. Accept any true wording, such as be nice to people the way you want people to be nice to you. For the second part, any real action: give somebody else a turn, pick up your own rubbish, share the swing, help a smaller child, wait in line. (HSS-1.1)"]}]},{id:29,title:"The Patch Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the pumpkin patch, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ico("mountain",56)}</td><td></td><td>${ico("scarecrow",56)}</td></tr>
     <tr><th>B</th><td>${ico("pumpkin",56)}</td><td>${ico("pumpkin",56)}</td><td>${ico("pumpkin",56)}</td></tr>
     <tr><th>C</th><td></td><td>${ico("cabin",56)}</td><td>${ico("tree",56)}</td></tr></table>
     <p class="big">${ico("mountain",48)} the hill &nbsp; ${ico("scarecrow",48)} the scarecrow &nbsp; ${ico("pumpkin",48)} the pumpkin rows &nbsp; ${ico("cabin",48)} the farm stand &nbsp; ${ico("tree",48)} the old oak</p>
     <p class="big">The top of this map is north. The bottom is south, the right is east, and the left is west.</p>
     <p class="big">This patch is in a town. The town is in the state of California, and California is one of the fifty states in a country called the United States.</p>`,qs:["Find the farm stand. Give its exact spot on the grid, the letter and the number.","Where is the hill compared to the farm stand? Use north, south, east or west.","Name one thing on this map that nature put there and one thing that people built.","Put these three in order, from the smallest to the biggest: the United States, your own town, California. Then say which one is a state and which one is a country."],key:["C2. Both parts are needed.","North of the farm stand and west of it. Both directions are needed for a full answer, and north west counts.","Needs both halves. Nature: the hill, the old oak. Built: the farm stand, the scarecrow.","your own town, then California, then the United States. California is the state and the United States is the country. Both parts are what is being checked. (HSS-1.2)"]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">On harvest day the table is full. It is the long table. It is at the patch. It is covered with food. The families brought it. They came from many different places. No two dishes are the same. They are all on the table.</p>
     <div class="figure">${ico("soup",88)}${ico("bread",88)}${ico("corn",88)}</div>`,qs:["Does everyone who lives in one town come from the same place? Say how the long table shows the answer.","Name two buildings people made in your own town, and say what each one is for.","Name one thing families in the same town might do differently from each other, and one thing they probably do the same."],key:["No. The families came from many different places, and the food they brought is all different.","Any two built places with a use: a school for learning, a store for buying food, a library for borrowing books, a fire station, a post office.","Needs both halves. Different: the food they cook, the language at home, the music they play. Same: going to work and school, shopping in the same stores, using the same roads and parks."]}]},{id:30,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling the difference between an ordinary object and a national symbol, and naming a national tradition",html:()=>`<p class="big">The Liberty Bell is very old. The bell is in Philadelphia. It cracked a long time ago. It is not rung any more. But people still come to look. They come from all over the country.</p>
     <div class="figure">${ico("flag",96)}${ico("star",96)}</div>`,qs:["The Liberty Bell is cracked and nobody rings it. So why do people still travel a long way to see it?","What is the difference between an ordinary bell on a school door and a symbol like the Liberty Bell?","Before a baseball game a whole crowd stands up and sings the same song, the national anthem. What does doing that together say about the people in the crowd?"],key:["Because it stands for something: the start of the country and the idea of being free. A symbol does its work even when it is broken.","The school bell is only a bell, used for ringing. The Liberty Bell stands for an idea that is bigger than the object itself.","That they belong to the same country, and that this is something people here do together. Any answer about belonging or doing it together counts."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Getting water on a farm.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>where it came from</td><td>a well dug in the yard</td><td>a pipe that runs to the house</td></tr>
     <tr><td>how it was carried</td><td>hauled up in a bucket on a rope</td><td>it comes out of a tap</td></tr>
     <tr><td>what people used it for</td><td>drinking, cooking, washing</td><td>drinking, cooking, washing</td></tr></table>
     <div class="figure">${ico("wateringCan",88)}${ico("drop",88)}</div>`,qs:["Long ago, where did a farm family get its water?","Where does water come from in a house today?","Which row of the chart shows something that is not done the way it used to be?","Which row of the chart is the same on both sides?"],key:["From a well dug in the yard, hauled up in a bucket on a rope.","Out of a tap, through a pipe that runs to the house.","Where it came from changed, or how it was carried changed. Either counts.","What people use water for: drinking, cooking and washing, the same then as now."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">A patch had 52 pumpkins. It sold 20 on Saturday. Then it sold 8 on Sunday. How many pumpkins are left?</p>`,key:["24 pumpkins (52 - 20 = 32, then 32 - 8 = 24)"]},3:{id:"L3",lv:true,title:"Level Up: Big Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["hayride","unload","slowly"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["hayride (two parts, ay and final e)","unload (prefix un-, vowel team oa)","slowly (suffix -ly, long o spelled ow)"]},6:{id:"L6",lv:true,title:"Level Up: Hundreds",std:["2.NBT.A.1"],needs:["1.NBT.B.2"],n:2,dir:"Look at the blocks. Answer out loud.",html:()=>`<div class="figure">${F.blocks(2,4,3)}</div><ol class="qlist"><li>How many hundreds, tens, and ones? What number is it?</li><li>What number has 5 hundreds, 0 tens, and 8 ones?</li></ol>`,key:["2 hundreds, 4 tens, and 3 ones. The number is 243","508"]},7:{id:"L7",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${JOB}</p><ol class="qlist"><li>Why did Jill run to get Russ?</li><li>How did Jill and Russ get the pumpkin up the hill?</li></ol>`,key:["The pumpkin was so big that Jill could not lift it. She needed help (or his wagon)","They set it in the red wagon and had to tug and tug"]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},blk=[0,0],c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function blkHtml(){return`<div class="blk-row"><button class="chip" data-b="0" data-d="1">Add a ten</button><button class="chip" data-b="0" data-d="-1">Take a ten</button><button class="chip" data-b="1" data-d="1">Add a one</button><button class="chip" data-b="1" data-d="-1">Take a one</button><button class="chip" data-b="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]?tens(blk[0],blk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} tens and ${blk[1]} ones on the mat.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I would take home the ____.","I pick it because ____.","That is why I pick the ____."],facts:["Fall is ____.","In fall, ____.","Another fact is ____.","Now you know about fall."],story:["One day, ____.","First, ____.","Next, ____.","Last, ____."]};function sentHtml(st){const wk=st&&st.parts&&st.parts[0]&&st.parts[0].wk||"facts";return`<ul class="starters">${(STARTERS[wk]||STARTERS.facts).map(x=>`<li>${x}</li>`).join("")}</ul>`}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:96,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{if(x.dataset.b==="x")blk=[0,0];else{const i=+x.dataset.b;blk[i]=Math.max(0,Math.min(i?19:9,blk[i]+ +x.dataset.d))}r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"nl",std:["1.OA.B.3"],msg:"1.OA.B.3 is about using number tricks (turn-around facts, making ten). If the student counts every hop on the number line, the stop shows counting, not the strategy."},{t:"blocks",std:["1.NBT.B.2"],msg:"If you build the number with blocks for questions 3 to 6, the stop shows reading a model, not knowing tens and ones from the written number."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows every numeral in order. If it was open, reading the number cards was reading from the chart, not from memory."},{t:"blocks",std:["1.NBT.C.4","1.NBT.C.6"],msg:"Building and taking apart tens with the blocks is allowed here, but note whether the student could also say what was added or taken away without them."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
